package me.trossty.car.sound;

import me.trossty.car.CarMain;
import net.minecraft.core.Holder;
import net.minecraft.core.Registry;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvent;

/**
 * Sounds the car uses.
 *
 * <p>Both are our own synthesized audio, not vanilla events. The sources live in
 * {@code sounds-src/} and are regenerated by {@code sounds-src/GenSounds.java};
 * the shipped {@code .ogg} files sit in {@code assets/overthought_vehicles/sounds/} and are
 * declared in {@code assets/overthought_vehicles/sounds.json}.
 *
 * <p>Both files are <strong>mono</strong> on purpose: Minecraft only pans and
 * attenuates single-channel audio. A stereo file would play at full volume
 * everywhere, so the car's engine would be audible across the whole world.
 */
public final class ModSounds {

    /**
     * The combustion engines' loops, by voice, band and layer, named
     * {@code engine_<voice>_<band>_<layer>}: each a seamless loop of the
     * engine firing at that layer's frequency. See {@link EngineAcoustics}
     * for how they are mixed.
     */
    private static final SoundEvent[][][] ENGINE_LOOPS =
            new SoundEvent[EngineAcoustics.Voice.values().length][EngineAcoustics.Band.values().length][EngineAcoustics.LAYERS];

    static {
        for (EngineAcoustics.Voice voice : EngineAcoustics.Voice.values()) {
            for (EngineAcoustics.Band band : EngineAcoustics.Band.values()) {
                for (int layer = 0; layer < EngineAcoustics.LAYERS; layer++) {
                    ENGINE_LOOPS[voice.ordinal()][band.ordinal()][layer] =
                            register("engine_" + voice.key() + "_" + band.key() + "_" + layer);
                }
            }
        }
    }

    /** A turbo's whine as its shaft spins, looped; pitched and swelled with the shaft's speed. */
    public static final SoundEvent TURBO_WHISTLE = register("turbo_whistle");

    /** One-shot horn blast: a 440 Hz / 554.37 Hz two-tone chord. */
    public static final Holder<SoundEvent> CAR_HORN = registerReference("horn");

    /** Tyre squeal for a car sliding sideways: a wavering whine over hiss. */
    public static final SoundEvent TYRE_SKID = register("skid");

    /** An electric motor's inverter whine: no firing, just a clean rising tone. */
    public static final SoundEvent ENGINE_ELECTRIC = register("engine_electric");

    /** The starter cranking and the engine catching, once, as somebody gets in. */
    public static final SoundEvent ENGINE_START = register("engine_start");

    /** A pop out of the tailpipe: a misfire, or unburnt fuel lighting off on a lift. */
    public static final SoundEvent BACKFIRE = register("backfire");

    /** A turbo's blow-off valve letting the boost go as the throttle shuts. */
    public static final SoundEvent BLOWOFF = register("blowoff");

    /** A light aircraft's engine and propeller, looped. */
    public static final SoundEvent ENGINE_PROPELLER = register("engine_propeller");

    /** An outboard motor, looped. */
    public static final SoundEvent ENGINE_OUTBOARD = register("engine_outboard");

    /** A generator set running, played now and then while it burns. */
    public static final SoundEvent GENERATOR_HUM = register("generator_hum");

    /** The pumpjack's beam: a thump and a long creak. */
    public static final SoundEvent PUMPJACK_CREAK = register("pumpjack_creak");

    /** Crude boiling in the refinery's column, and the hydrotreater's reactor. */
    public static final SoundEvent REFINERY_BUBBLE = register("refinery_bubble");

    /** A charging post putting power into a car. */
    public static final SoundEvent CHARGER_HUM = register("charger_hum");

    private ModSounds() {
    }

    public static SoundEvent engineLoop(EngineAcoustics.Voice voice, EngineAcoustics.Band band, int layer) {
        return ENGINE_LOOPS[voice.ordinal()][band.ordinal()][layer];
    }

    private static SoundEvent register(String path) {
        ResourceLocation id = CarMain.id(path);
        return Registry.register(BuiltInRegistries.SOUND_EVENT, id, SoundEvent.createVariableRangeEvent(id));
    }

    private static Holder.Reference<SoundEvent> registerReference(String path) {
        ResourceLocation id = CarMain.id(path);
        return Registry.registerForHolder(BuiltInRegistries.SOUND_EVENT, id, SoundEvent.createVariableRangeEvent(id));
    }

    /** Forces class loading so the static fields above are registered. */
    public static void register() {
    }
}
